import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import BookingList from "../components/BookingList";
import BookingForm from "../components/BookingForm";
import Sidebar from "../components/Sidebar";
import Navbar from "../components/Navbar";
import api from "../services/api";

const ClientDashboard = ({ view = "overview" }) => {
  const navigate = useNavigate();

  const [bookings, setBookings] = useState([]);
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    approved: 0,
    rejected: 0,
  });

  const [loading, setLoading] = useState(true);

  const [formData, setFormData] = useState({
    resourceScope: "block",
    blockId: "",
    resourceId: "",
    name: "",
    department: "",
    bookingDate: "",
    startTime: "",
    endTime: "",
    purpose: "",
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    alert("Booking Created!");
  };

  const fetchDashboard = useCallback(async () => {
    try {
      setLoading(true);

      const res = await api.get("/client/bookings");
      const data = res.data || [];

      setBookings(data);

      const getStatus = (b) =>
        (b.status || b.booking_status || "").toLowerCase();

      setStats({
        total: data.length,
        pending: data.filter((b) => getStatus(b) === "pending").length,
        approved: data.filter((b) => getStatus(b) === "approved").length,
        rejected: data.filter((b) => getStatus(b) === "rejected").length,
      });
    } catch (err) {
      console.log(err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchDashboard();
  }, [fetchDashboard]);

  const menuItems = [
    { key: "overview", label: "Overview", to: "/" },
    { key: "new-booking", label: "New Booking", to: "/new-booking" },
    { key: "my-bookings", label: "My Bookings", to: "/my-bookings" },
  ];

  const renderContent = () => {
    if (view === "new-booking") {
      return (
        <BookingForm
          formData={formData}
          onChange={handleChange}
          onSubmit={handleSubmit}
        />
      );
    }

    if (view === "my-bookings") {
      return <BookingList bookings={bookings} />;
    }

    return (
      <>
        {/* 🔥 MODERN STATS */}
        <div className="stats-container">
          <div className="card blue">
            <p>Total</p>
            <h2>{stats.total}</h2>
          </div>
          <div className="card yellow">
            <p>Pending</p>
            <h2>{stats.pending}</h2>
          </div>
          <div className="card green">
            <p>Approved</p>
            <h2>{stats.approved}</h2>
          </div>
          <div className="card red">
            <p>Rejected</p>
            <h2>{stats.rejected}</h2>
          </div>
        </div>

        <BookingList bookings={bookings.slice(0, 3)} />
      </>
    );
  };

  return (
    <div className="dashboard">
      <Sidebar items={menuItems} onLogout={() => navigate("/login")} />

      <div className="main">
        <Navbar title="Dashboard" />

        {loading ? <p>Loading...</p> : renderContent()}
      </div>
    </div>
  );
};

export default ClientDashboard;
